head.b:skin:
/* =========================
   AL-AMEEN INTERNET PORTAL
   PREMIUM BLOGGER TEMPLATE
========================= */

/* COLORS */

:root {
 --navy:#07182E;
 --navy2:#0B2545;
 --blue:#123F73;
 --blue2:#1765A5;
 --cyan:#32C5E8;
 --gold:#D6B56D;
 --white:#F7FAFD;
 --text:#24364B;
 --muted:#718096;
 --border:#E5EDF5;
}

/* GENERAL */

* {
 box-sizing:border-box;
}

html {
 scroll-behavior:smooth;
}

body {
 margin:0;
 padding:0;
 background:#F4F7FB;
 color:var(--text);
 font-family:Tahoma,Arial,sans-serif;
 direction:rtl;
 line-height:1.9;
}

a {
 text-decoration:none;
}

img {
 max-width:100%;
 height:auto;
}

.container {
 width:90%;
 max-width:1200px;
 margin:auto;
}

/* HEADER */

.site-header {
 background:var(--navy);
 color:white;
 position:relative;
 z-index:100;
 border-bottom:1px solid rgba(50,197,232,.3);
}

.header-inner {
 min-height:85px;
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:25px;
}

.brand {
 display:flex;
 align-items:center;
 gap:13px;
 color:white;
}

.brand-icon {
 width:52px;
 height:52px;
 border-radius:15px;
 background:linear-gradient(135deg,var(--cyan),var(--blue));
 display:flex;
 justify-content:center;
 align-items:center;
 font-size:26px;
 box-shadow:0 5px 20px rgba(50,197,232,.2);
}

.brand-name {
 font-size:22px;
 font-weight:bold;
}

.brand-name span {
 color:var(--cyan);
}

.brand-name small {
 display:block;
 font-size:10px;
 letter-spacing:2px;
 color:#AFC5DA;
 font-weight:normal;
 direction:ltr;
 text-align:right;
}

/* NAVIGATION */

.nav-area {
 display:flex;
 align-items:center;
 gap:20px;
}

.nav-area .widget {
 margin:0;
}

.nav-area .widget h2 {
 display:none;
}

.nav-area .PageList ul {
 list-style:none;
 padding:0;
 margin:0;
 display:flex;
 flex-wrap:wrap;
 gap:22px;
}

.nav-area .PageList li {
 list-style:none;
}

.nav-area .PageList a {
 color:#EAF4FF;
 font-size:13px;
 transition:.3s;
}

.nav-area .PageList a:hover {
 color:var(--cyan);
}

/* HERO */

.hero {
 position:relative;
 overflow:hidden;
 background:
 radial-gradient(circle at 85% 20%,rgba(50,197,232,.18),transparent 28%),
 radial-gradient(circle at 10% 90%,rgba(214,181,109,.12),transparent 30%),
 linear-gradient(125deg,#06152A,#0B2D55 60%,#104D7C);
 color:white;
 padding:105px 20px 115px;
}

.hero:before {
 content:"";
 position:absolute;
 width:400px;
 height:400px;
 border:1px solid rgba(50,197,232,.12);
 border-radius:50%;
 left:-120px;
 top:-180px;
 box-shadow:0 0 0 35px rgba(50,197,232,.025),
            0 0 0 75px rgba(50,197,232,.02);
}

.hero-content {
 position:relative;
 z-index:2;
 max-width:850px;
 margin:auto;
 text-align:center;
}

.hero-label {
 display:inline-block;
 color:var(--cyan);
 border:1px solid rgba(50,197,232,.4);
 border-radius:30px;
 padding:5px 20px;
 font-size:12px;
 letter-spacing:1px;
}

.hero h1 {
 font-size:48px;
 line-height:1.5;
 margin:25px 0 10px;
}

.hero h1 span {
 color:var(--cyan);
}

.hero p {
 max-width:700px;
 margin:15px auto 30px;
 color:#D4E3F1;
 font-size:17px;
}

.hero-buttons {
 display:flex;
 justify-content:center;
 flex-wrap:wrap;
 gap:12px;
}

/* BUTTONS */

.btn {
 display:inline-block;
 padding:12px 28px;
 border-radius:9px;
 font-size:14px;
 font-weight:bold;
 transition:.3s;
}

.btn-primary {
 background:linear-gradient(135deg,var(--cyan),#159ACB);
 color:#06213C;
 box-shadow:0 8px 22px rgba(50,197,232,.2);
}

.btn-primary:hover {
 transform:translateY(-4px);
 box-shadow:0 12px 28px rgba(50,197,232,.3);
}

.btn-outline {
 color:white;
 border:1px solid rgba(255,255,255,.5);
}

.btn-outline:hover {
 background:white;
 color:var(--navy);
}

/* SECTION */

.section {
 padding:75px 0;
}

.section-heading {
 text-align:center;
 margin-bottom:42px;
}

.section-heading .mini-title {
 color:#138EBB;
 font-weight:bold;
 font-size:12px;
 letter-spacing:2px;
}

.section-heading h2 {
 font-size:31px;
 color:var(--navy);
 margin:8px 0;
}

.section-heading p {
 color:var(--muted);
 margin:0;
}

/* SERVICES */

.services-grid {
 display:grid;
 grid-template-columns:repeat(3,1fr);
 gap:22px;
}

.service-card {
 display:block;
 color:inherit;
 text-decoration:none;
 background:white;
 padding:30px 24px;
 border-radius:16px;
 border:1px solid var(--border);
 box-shadow:0 8px 30px rgba(13,45,78,.045);
 transition:.3s;
 position:relative;
 overflow:hidden;
}

.service-card:after {
 content:"";
 position:absolute;
 bottom:0;
 right:0;
 width:0;
 height:3px;
 background:var(--cyan);
 transition:.3s;
}

.service-card:hover {
 transform:translateY(-7px);
 box-shadow:0 15px 35px rgba(13,45,78,.09);
}

.service-card:hover:after {
 width:100%;
}

.service-icon {
 width:58px;
 height:58px;
 display:flex;
 justify-content:center;
 align-items:center;
 border-radius:15px;
 background:#E9F8FD;
 font-size:27px;
}

.service-card h3 {
 color:var(--blue);
 font-size:19px;
 margin:17px 0 7px;
}

.service-card p {
 color:var(--muted);
 font-size:13px;
 margin:0;
}

/* ABOUT */

.about-box {
 display:grid;
 grid-template-columns:1fr 1fr;
 gap:35px;
 align-items:center;
 background:white;
 padding:38px;
 border-radius:20px;
 border:1px solid var(--border);
}

.about-box h2 {
 color:var(--navy);
 font-size:29px;
}

.about-box p {
 color:var(--muted);
}

.about-visual {
 min-height:250px;
 border-radius:17px;
 background:
 radial-gradient(circle at center,rgba(50,197,232,.2),transparent 45%),
 linear-gradient(135deg,#0A2444,#155B91);
 display:flex;
 align-items:center;
 justify-content:center;
 color:white;
 font-size:70px;
}

/* CARDS */

.internet-box {
 background:white;
 border:1px solid var(--border);
 padding:35px;
 border-radius:18px;
 text-align:center;
}

.internet-box h3 {
 color:var(--blue);
 font-size:23px;
}

.internet-box p {
 color:var(--muted);
}

/* REQUEST */

.request-section {
 background:linear-gradient(120deg,#0A2444,#104B7D);
 padding:65px 20px;
 text-align:center;
 color:white;
}

.request-section h2 {
 font-size:30px;
 margin:0 0 10px;
}

.request-section p {
 color:#D1E3F2;
 margin-bottom:25px;
}

/* CONTACT */

.contact-grid {
 display:grid;
 grid-template-columns:repeat(3,1fr);
 gap:20px;
}

.contact-card {
 display:block;
 color:inherit;
 text-decoration:none;
 background:white;
 border:1px solid var(--border);
 border-radius:14px;
 padding:25px;
 text-align:center;
}

.contact-grid .contact-card {
 grid-column:1 / -1;
 width:100%;
 max-width:360px;
 justify-self:center;
}

.contact-card .icon {
 font-size:32px;
}

.contact-card h3 {
 color:var(--blue);
}

/* PAGE CONTENT */

.page-wrapper {
 width:90%;
 max-width:1100px;
 margin:45px auto;
 background:white;
 padding:35px;
 border-radius:16px;
 border:1px solid var(--border);
 box-shadow:0 8px 30px rgba(0,0,0,.035);
 min-height:300px;
}

.page-wrapper h1,
.page-wrapper h2 {
 color:var(--blue);
}

.page-wrapper img {
 border-radius:12px;
}

/* BLOGGER WIDGETS */

.main-section .widget h2 {
 color:var(--blue);
}

.blog-posts {
 line-height:2;
}

/* FOOTER */

.site-footer {
 background:#061426;
 color:#AFC1D4;
 padding:55px 0 20px;
}

.footer-grid {
 display:grid;
 grid-template-columns:2fr 1fr 1fr;
 gap:35px;
}

.site-footer h3 {
 color:white;
}

.site-footer h3 span {
 color:var(--cyan);
}

.site-footer a {
 display:block;
 color:#B9CADD;
 font-size:13px;
 margin:8px 0;
}

.site-footer a:hover {
 color:var(--cyan);
}

.footer-bottom {
 border-top:1px solid rgba(255,255,255,.1);
 margin-top:35px;
 padding-top:18px;
 text-align:center;
 font-size:12px;
}

/* MOBILE */

@media(max-width:900px) {

 .header-inner {
  padding:15px 0;
  flex-direction:column;
 }

 .nav-area {
  width:100%;
  justify-content:center;
 }

 .nav-area .PageList ul {
  justify-content:center;
  gap:13px;
 }

 .services-grid {
  grid-template-columns:repeat(2,1fr);
 }

 .contact-grid {
  grid-template-columns:1fr 1fr;
 }

}

@media(max-width:600px) {

 .hero {
  padding:75px 15px;
 }

 .hero h1 {
  font-size:31px;
 }

 .hero p {
  font-size:14px;
 }

 .section {
  padding:50px 0;
 }

 .section-heading h2 {
  font-size:25px;
 }

 .services-grid,
 .contact-grid,
 .footer-grid,
 .about-box {
  grid-template-columns:1fr;
 }

 .about-box {
  padding:22px;
 }

 .page-wrapper {
  padding:20px;
 }

 .nav-area .PageList ul {
  gap:8px 13px;
 }

 .nav-area .PageList a {
  font-size:12px;
 }

}

/* ANIMATION */

@keyframes fadeUp {
 from {
  opacity:0;
  transform:translateY(20px);
 }
 to {
  opacity:1;
  transform:translateY(0);
 }
}

.hero-content {
 animation:fadeUp .8s ease both;
}


/* AL-AMEEN REQUESTED PAGE ENHANCEMENTS */
.portal-page { width:90%; max-width:1100px; margin:45px auto; }
 .portal-grid-two { max-width:760px; margin-left:auto; margin-right:auto; }
.portal-heading { text-align:center; margin:0 0 32px; }
.portal-heading h1,.portal-heading h2 { color:var(--navy); margin:0 0 8px; }
.portal-heading p { color:var(--muted); margin:0; }
.portal-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px; }
.portal-card { display:block; background:#fff; border:1px solid var(--border); border-radius:16px; padding:26px 22px; box-shadow:0 8px 28px rgba(13,45,78,.05); transition:transform .25s,box-shadow .25s,border-color .25s; color:var(--text); text-align:center; }
.portal-card:hover { transform:translateY(-5px); box-shadow:0 14px 32px rgba(13,45,78,.11); border-color:var(--cyan); }
.portal-card .portal-icon { width:58px; height:58px; margin:0 auto 12px; border-radius:16px; display:flex; align-items:center; justify-content:center; background:#E9F8FD; font-size:27px; }
.portal-card h3 { color:var(--blue); margin:8px 0; font-size:19px; }
.portal-card p { color:var(--muted); margin:4px 0 14px; font-size:14px; }
.portal-price { color:var(--navy); font-size:21px; font-weight:bold; margin:8px 0; }
.portal-capacity { color:var(--muted); font-size:14px; }
.portal-action { display:inline-block; margin-top:12px; padding:9px 20px; border-radius:8px; background:var(--blue2); color:#fff; font-weight:bold; font-size:13px; }

/* Router and wireless equipment gallery */
.device-gallery-heading { text-align:center; margin:48px 0 24px; }
.device-gallery-heading h2 { color:var(--navy); margin:0 0 8px; }
.device-gallery-heading p { color:var(--muted); margin:0; }
.device-gallery { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px; }
.device-card { overflow:hidden; background:#fff; border:1px solid var(--border); border-radius:17px; box-shadow:0 8px 26px rgba(13,45,78,.06); transition:transform .25s,box-shadow .25s,border-color .25s; }
.device-card:hover { transform:translateY(-4px); border-color:var(--cyan); box-shadow:0 14px 30px rgba(13,45,78,.11); }
.device-photo { height:205px; padding:12px; display:flex; align-items:center; justify-content:center; background:linear-gradient(180deg,#f8fbfe,#edf4f9); }
.device-photo img { width:100%; height:100%; object-fit:contain; display:block; }
.device-info { padding:17px 18px 19px; text-align:right; }
.device-topline { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:9px; }
.device-number { color:var(--blue); background:#e8f7fc; border:1px solid #cceef7; border-radius:30px; padding:4px 10px; font-size:12px; font-weight:bold; direction:ltr; }
.device-type { color:#648096; font-size:11px; font-weight:bold; }
.device-info h3 { color:var(--navy); font-size:17px; margin:0 0 8px; }
.device-info p { color:var(--muted); font-size:13px; line-height:1.9; margin:0; }
.device-note { margin-top:22px; padding:13px 16px; border-right:3px solid var(--cyan); border-radius:9px; background:#f3f9fc; color:#476176; font-size:12px; line-height:1.9; }
@media(max-width:900px) { .device-gallery { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:520px) { .device-gallery { grid-template-columns:1fr; } .device-photo { height:220px; } }

.portal-subheading { margin:48px 0 22px; text-align:center; color:var(--navy); }
.portal-contact-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; max-width:850px; margin:auto; }
.portal-contact-link { display:flex; min-height:135px; flex-direction:column; justify-content:center; align-items:center; gap:12px; border:1px solid var(--border); border-radius:16px; background:#fff; color:var(--blue); font-size:15px; font-weight:bold; box-shadow:0 8px 25px rgba(13,45,78,.05); transition:.25s; }
.portal-contact-link:hover { transform:translateY(-5px); border-color:var(--cyan); box-shadow:0 12px 28px rgba(13,45,78,.1); }
.portal-contact-link .portal-icon { font-size:32px; }
.site-footer a { display:block; }
@media(max-width:700px) {
 .portal-grid { grid-template-columns:1fr; }
 .portal-contact-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
 .portal-page { margin:28px auto; }
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
document.addEventListener('change', function(event) {
  var el = event.target;
  if (el && el.tagName === 'SELECT' && /_select$/.test(el.id) && el.value) {
    window.location.href = el.value;
  }
});
//
